(function () {
  var dict = window.LUCIEN_I18N, fr = {};
  document.querySelectorAll("[data-i18n]").forEach(function (el) { fr[el.getAttribute("data-i18n")] = el.innerHTML; });
  document.querySelectorAll("[data-i18n-ph]").forEach(function (el) { fr[el.getAttribute("data-i18n-ph")] = el.getAttribute("placeholder"); });
  var frDesc = (document.querySelector('meta[name="description"]') || {}).content || "";
  fr.vpause = "Mettre la vidéo en pause"; fr.vplay = "Lire la vidéo"; fr.tm = "/ mois"; fr.ta = "/ an"; fr.peq = "soit {x} / mois"; fr.peq2 = "sans engagement";
  fr.s8 = "Soit {x} par mois qui partent pour rien."; fr.s15 = "Choisissez « Je n'y vais plus » pour ce qui ne sert plus."; fr.s16 = "Vous gardez {x} par an d'abonnements utiles : Lucien surveille aussi qu'ils n'augmentent pas en douce.";
  fr.ok = "C'est noté. Vous recevrez une invitation dès l'ouverture."; fr.bad = "Vérifiez l'adresse email."; fr.fail = "L'inscription n'a pas pu être enregistrée depuis cette page."; fr.copied = "Adresse copiée."; fr.wait = "Un instant…";
  dict.fr = Object.assign({ _dir: "ltr", _desc: frDesc }, fr);

  window.LUCIEN_LANG = "fr";
  window.lucienT = function (key) { return (dict[window.LUCIEN_LANG] || dict.fr)[key] || dict.fr[key] || ""; };

  function apply(lang) {
    var d = dict[lang] || dict.fr;
    document.querySelectorAll("[data-i18n]").forEach(function (el) { var k = el.getAttribute("data-i18n"); if (d[k] != null) el.innerHTML = d[k]; });
    document.querySelectorAll("[data-i18n-ph]").forEach(function (el) { var k = el.getAttribute("data-i18n-ph"); if (d[k]) el.setAttribute("placeholder", d[k]); });
    document.documentElement.lang = lang;
    document.documentElement.dir = d._dir || "ltr";
    var m = document.querySelector('meta[name="description"]'); if (m && d._desc) m.content = d._desc;
    window.LUCIEN_LANG = lang;
    var sel = document.getElementById("lang"); if (sel && sel.value !== lang) sel.value = lang;
    try { localStorage.setItem("lucien.lang", lang); } catch (e) {}
    try { window.dispatchEvent(new Event("lucien:lang")); } catch (e) {}
  }

  var initial = "fr";
  try { initial = localStorage.getItem("lucien.lang") || localStorage.getItem("nidou.lang") || ""; } catch (e) {}
  if (!initial) {
    var nav = ((navigator.languages && navigator.languages[0]) || navigator.language || "fr").slice(0, 2).toLowerCase();
    initial = dict[nav] ? nav : "fr";
  }
  if (initial !== "fr") apply(initial);
  var sel = document.getElementById("lang");
  if (sel) { sel.value = initial; sel.addEventListener("change", function () { apply(sel.value); }); }
})();
